def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_score = 0
    opp_score = 0
    for i, (a, b) in enumerate(history):
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1

    opp_defects = sum(1 for _, b in history if b == 'D')
    my_defects = sum(1 for a, _ in history if a == 'D')
    last_my, last_opp = history[-1]

    if n < 5:
        return 'C'

    recent = history[-5:]
    recent_opp_defects = sum(1 for _, b in recent if b == 'D')
    recent_my_defects = sum(1 for a, _ in recent if a == 'D')

    if recent_opp_defects == 0:
        return 'C'

    if recent_opp_defects >= 4:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    if recent_opp_defects >= 2:
        if recent_my_defects >= 3:
            return 'C'
        if last_opp == 'D' and last_my == 'D':
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if rng.random() < 0.65:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_my == 'C':
            if rng.random() < 0.9:
                return 'D'
            return 'C'
        else:
            if rng.random() < 0.3:
                return 'C'
            return 'D'

    if opp_score > my_score + 8:
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    return 'C'
